head.script:
scwin.gAcptNo;
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_4);
        panel_mkt_gubun.hide();
        panel_mkt_gubun2.hide();
        MxTab_1.setSelectedTabIndex("1");
        await scwin.setCode();

        // 두번째 탭 회사검색
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        $c.stf.comboCbDataSetPeriod(cmb_Tab1_PeriodTp);
        $c.stf.comboCbDataSetPeriod(cmb_Tab2_PeriodTp);
        await scwin.checkCond();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15640.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

