 * @method
 * @name btn_Tab2_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Tab2_Excel_onclick = function() {
    try {
        let secuGrpNm = "";
        if (chb_SecuRT.getValue() === '1') secuGrpNm = "부동산투자";
        if (chb_SecuSC.getValue() === '1') secuGrpNm = "선박투자";
        if (chb_SecuMT.getValue() === '1') secuGrpNm = "투자회사";
        if (chb_SecuAA.getValue() === ' 1') secuGrpNm = "전체";
        $c.stf.doLogSave('ULDSTF15640.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid2, {fileName: secuGrpNm + " 공시상세검색  목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15640.btn_Tab2_Excel_onclick" });
    }
};

