scwin.img_Tab2_FindForm_onclick = async function() {
    try {
        // *** 셋팅할 필드명 정의를 아래처럼 해야함.
        // => 보고서명: txb_FormNm, 보고서코드 : txb_FormCd
        const url = "/common/ULDSTF91003.gfm";
        const winTitle = "공시제목선택 ";
        await $c.frame.CreateDialogFrame("FORMLIST", url, winTitle, 100, 10, 700, 570, "window");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15640.img_Tab2_FindForm_onclick" });
    }
};

