///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    chb_SecuAA.setValue(1);
    if (js_market === "9") {
        rdo_Tab1_MARKET_TP_CD.setValue("A");
        rdo_Tab2_MARKET_TP_CD.setValue("A");
    } else {
        rdo_Tab1_MARKET_TP_CD.setValue(js_market);
        rdo_Tab2_MARKET_TP_CD.setValue(js_market);
    }

    // 위탁회사명
    const sbmOptions = {
        id : "sbm_dts_BCComList",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_BCComList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 수익증권 서식목록
    const sbmOptions2 = {
        id : "sbm_dts_FormCdList",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_FormCdList=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    //  Tab1 : 기간 from~ to  셋팅
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_Tab1_FromDate.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 7일전 날짜
