///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkCond
 * @description check Cond 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCond = async function() {
    if (MxTab_1.getSelectedTabIndex() === 1) {
        // 일자 체크
        if (edt_Tab1_FromDate.getValue().length < 8) {
            await $c.win.alert("일자 올바르게 입력하십시오.");
            edt_Tab1_FromDate.focus();
            return;
        }

        // 일자 체크
        if (edt_Tab1_ToDate.getValue().length < 8) {
            await $c.win.alert("일자 올바르게 입력하십시오.");
            edt_Tab1_ToDate.focus();
            return;
        }
        if ($c.stf.compareFromToDate2(edt_Tab1_FromDate, edt_Tab1_ToDate) === false) {
            return;
        }
        await scwin.search1();
    } else if (MxTab_1.getSelectedTabIndex() === 2) {
        // 일자 체크
        if (edt_Tab2_FromDate.getValue().length < 8) {
            await $c.win.alert("일자 올바르게 입력하십시오.");
            edt_Tab2_FromDate.focus();
            return;
        }

        // 일자 체크
        if (edt_Tab2_ToDate.getValue().length < 8) {
            await $c.win.alert("일자 올바르게 입력하십시오.");
            edt_Tab2_ToDate.focus();
            return;
        }
        if ($c.stf.compareFromToDate2(edt_Tab2_FromDate, edt_Tab2_ToDate) === false) {
            return;
        }

        // 보고서 코드 체크
        const vFormCd2 = txb_FormCd.getValue();
        if (vFormCd2.length > 0 && vFormCd2.length !== 5) {
            await $c.win.alert("보고서코드 5자리를 입력하십시오.");
            txb_FormCd.focus();
            return;
        }
        await scwin.search2();
    }
};

/**
 * @method
 * @name allCheck
 * @description all Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck = function() {
    const checkArray = [chb_SecuRT, chb_SecuSC, chb_SecuMT];
    if (chb_SecuAA.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "";
    }
};

